class ConfIndicadorespagosporresultados extends BaseConfIndicadorespagosporresultados
{
    /**
     * Obtener un listado de los datos de los tipos de pago.
     *
     * @param int $inicio Inicio de la busqueda.
     * @param int $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de los tipos de pago.obtenerConfpagosporresultados
     */

    public function getByid($idindicadorespagoresultado)
    {
        return Doctrine::getTable('ConfIndicadorespagosporresultados')->find($idindicadorespagoresultado);
    }

    public function findByIdOrDenom($denom, $idpagoporresultado)
    {
        try {
            $query = Doctrine_Query::create()
                ->select('*')
                ->from('ConfIndicadorespagosporresultados')
                ->where("denominacion ilike '$denom' and idpagoporresultado = ?", array($idpagoporresultado));
            return $query->execute()->toArray();

        } catch (Doctrine_Exception $e) {
            throw $e;
        }
    }

    public static function ObtenerIndicadorespagosporresultadosid($idpagoporresultado)
    {
        //Devolviendo el listado de tipos de pago en forma de arreglo.
        return Doctrine_Query::create()
            ->select('ipr.*')
            ->from('ConfIndicadorespagosporresultados ipr')
            ->where('ipr.idpagoporresultado = ?', array($idpagoporresultado))
            ->orderBy('ipr.orden')
            ->fetchArray();
    }

    public static function ObtenerIndicadorCampoNomina($idconfpagoresultado)
    {
        //Devolviendo el listado de tipos de pago en forma de arreglo.
        return Doctrine_Query::create()
            ->select('idestructuramodelonomina')
            ->from('ConfIndicadorespagosporresultados ipr')
            ->where('ipr.idpagoporresultado = ? and ipr.tipovalor = 1', array($idconfpagoresultado))
            ->orderBy('ipr.orden')
            ->fetchOne()
            ->idestructuramodelonomina;
    }
	
	public static function ObtenerIndicadoresCampoNomina($idconfpagoresultado)
    {
        //Devolviendo el listado de tipos de pago en forma de arreglo.
        return Doctrine_Query::create()
            ->select('idestructuramodelonomina, denominacion')
            ->from('ConfIndicadorespagosporresultados ipr')
            ->where('ipr.idpagoporresultado = ? and ipr.tipovalor = 1', array($idconfpagoresultado))
            ->orderBy('ipr.orden')
            ->fetchArray();
    }

    public static function ObtenerMaxOrden($id)
    {
        //Devolviendo el listado de tipos de pago en forma de arreglo.
        $query = Doctrine_Query::create()
            ->select('max(ipr.orden)')
            ->from('ConfIndicadorespagosporresultados ipr')
            ->where("ipr.idpagoporresultado = $id");
        return $query->execute()->toArray();
    }

    public static function Ordenar($orden)
    {
        //Devolviendo el listado de tipos de pago en forma de arreglo.
        $query = Doctrine_Query::create()
            ->update()
            ->from('ConfIndicadorespagosporresultados ipr')
            ->set('ipr.orden ', 'ipr.orden - 1')
            ->where("ipr.orden > $orden");
        return $query->execute();
    }

    public static function OrdenarASc($orden, $id)
    {
        //Devolviendo el listado de tipos de pago en forma de arreglo.
        $query = Doctrine_Query::create()
            ->update()
            ->from('ConfIndicadorespagosporresultados ipr')
            ->set('ipr.orden ', 'ipr.orden + 1')
            ->where("ipr.orden = $orden-1")
            ->andWhere("ipr.idpagoporresultado = $id");
        return $query->execute();
    }

    public static function OrdenarDes($orden, $id)
    {
        //Devolviendo el listado de tipos de pago en forma de arreglo.
        $query = Doctrine_Query::create()
            ->update()
            ->from('ConfIndicadorespagosporresultados ipr')
            ->set('ipr.orden ', 'ipr.orden - 1')
            ->where("ipr.orden = $orden+1")
            ->andWhere("ipr.idpagoporresultado = $id");
        return $query->execute();
    }

    public static function obtenerExpresionesMatXIdIndicadoresPR($idindicadorpagoresultado)
    {
        //Devolviendo el listado de tipos de pago en forma de arreglo.
        return Doctrine_Query::create()
            ->select('cipr.tipovalor, cipr.expresionmatematicaindicador, cipr.expresionmatematicaformula, cipr.orden')
            ->from('ConfIndicadorespagosporresultados cipr')
            ->where('idindicadorespagoresultado = ?', $idindicadorpagoresultado)
            ->orderBy('cipr.orden')
            ->fetchArray();
    }

    public static function ObtenerIndicadoresCampoNominaElaborarPagos($idconfpagoresultado, $idelaborarpagos)
    {
        //Devolviendo el listado de tipos de pago en forma de arreglo.
        $sqlIndicador = "select ipr.idestructuramodelonomina, ipr.denominacion, ipr.idindicadorespagoresultado
                from mod_nomina.conf_indicadorespagoporresultado ipr
                inner join  mod_nomina.conf_estructuramodelosnomina cemn on (cemn.idestructuramodelodomina = ipr.idestructuramodelonomina)
                inner join  mod_nomina.conf_modelonomina mn on (mn.idtiponomina = cemn.idtiponomina)
                inner join  mod_nomina.dat_elaborarpagos ep on (ep.idtipopago = mn.idtipopago)
                where ipr.idpagoporresultado = ? and ipr.tipovalor = 1 and ep.idelaborarpagos = ? order by ipr.orden ASC";
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $arrIndicador = $conn->fetchAll($sqlIndicador, array($idconfpagoresultado, $idelaborarpagos));
        return $arrIndicador;
    }

    public static function eliminarIndicadoresCampoNominaXidPagosPorResultado($idpagoporresultado)
    {
        $sqlIndicador = "DELETE FROM mod_nomina.conf_indicadorespagoporresultado WHERE idpagoporresultado = $idpagoporresultado;";
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $conn->execute($sqlIndicador);
    }
}
